#!/usr/bin/env python3
"""Finite arithmetic checks for cyclic fixed-stabilizer quotient groups.

The algebraic and topological input is proved separately in the accompanying paper.
"""
from math import gcd

def prime_factors(n):
    out = set()
    m = n
    p = 2
    while p * p <= m:
        if m % p == 0:
            out.add(p)
            while m % p == 0:
                m //= p
        p += 1
    if m > 1:
        out.add(m)
    return out

def group_index(k, s):
    # H=<phi^s> has elements phi^(s*j), j mod k/s.
    # Its stabilizer-generated subgroup is generated by the j's with gcd(s*j,k)>1.
    size = k // s
    step = size
    for j in range(1, size):
        if gcd(s * j, k) > 1:
            step = gcd(step, j)
    return step

for k in range(2, 241):
    p = prime_factors(k)
    predicted = next(iter(p)) if len(p) == 1 else 1
    assert group_index(k, 1) == predicted, (k, predicted)
    for s in range(2, k + 1):
        if k % s == 0:
            assert group_index(k, s) == 1, (k, s)
print('VERIFY_OK cyclic_fixed_subgroups_k=2..240 prime_power_dichotomy=true all_intermediate_quotients=true')
